#!/usr/bin/env python3
"""Merge user records from JSON, CSV, and Parquet sources.

Priority: source_a > source_b > source_c.
"""

import json
import math
import re

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

SOURCES = ("source_a", "source_b", "source_c")

# Canonical field -> per-source column candidates (in priority order within a source).
FIELD_MAP = {
    "user_id": {"source_a": ("user_id", "id", "userId"),
                "source_b": ("user_id", "id", "userId"),
                "source_c": ("user_id", "id", "userId")},
    "name": {"source_a": ("full_name", "name", "userName"),
             "source_b": ("full_name", "name", "userName"),
             "source_c": ("full_name", "name", "userName")},
    "email": {"source_a": ("email", "email_address"),
              "source_b": ("email", "email_address"),
              "source_c": ("email", "email_address")},
    "created_date": {"source_a": ("registration_date", "created_at", "joined"),
                     "source_b": ("registration_date", "created_at", "joined"),
                     "source_c": ("registration_date", "created_at", "joined")},
    "status": {"source_a": ("status", "is_active", "active"),
               "source_b": ("status", "is_active", "active"),
               "source_c": ("status", "is_active", "active")},
}

# Fields written to the output, in output order.
OUTPUT_FIELDS = ("user_id", "name", "email", "created_date", "status")


def is_missing(value):
    if value is None:
        return True
    if isinstance(value, float) and math.isnan(value):
        return True
    if isinstance(value, str) and value.strip() == "":
        return True
    return False


def clean_text(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text if text else None


def clean_user_id(value):
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int,)):
        return int(value)
    if isinstance(value, float):
        return int(value) if value.is_integer() else None
    text = str(value).strip()
    if re.fullmatch(r"[+-]?\d+", text):
        return int(text)
    try:
        number = float(text)
    except ValueError:
        return None
    return int(number) if number.is_integer() else None


def clean_date(value):
    """Normalize a date to YYYY-MM-DD; return None if it cannot be parsed."""
    text = clean_text(value)
    if text is None:
        return None
    # Already an ISO date (optionally with a time component).
    match = re.match(r"^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$", text)
    if match:
        return f"{match.group(1)}-{match.group(2)}-{match.group(3)}"
    # Slash-separated dates: assume month/day/year when ambiguous.
    match = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", text)
    if match:
        month, day, year = match.groups()
        return f"{year}-{int(month):02d}-{int(day):02d}"
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return None
    return parsed.strftime("%Y-%m-%d")


def clean_status(value):
    """Normalize boolean-ish activity flags to a status string."""
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)):
        if value == 1:
            return "active"
        if value == 0:
            return "inactive"
    text = str(value).strip()
    lowered = text.lower()
    if lowered in {"true", "t", "yes", "y", "1", "active", "enabled"}:
        return "active"
    if lowered in {"false", "f", "no", "n", "0", "inactive", "disabled"}:
        return "inactive"
    return text


CLEANERS = {
    "user_id": clean_user_id,
    "name": clean_text,
    "email": clean_text,
    "created_date": clean_date,
    "status": clean_status,
}


def load_source_a(path):
    with open(path, "r", encoding="utf-8") as handle:
        data = json.load(handle)
    if isinstance(data, dict):
        # Accept {"users": [...]} or a single record.
        for key in ("users", "data", "records"):
            if isinstance(data.get(key), list):
                data = data[key]
                break
        else:
            data = [data]
    return pd.DataFrame(data)


def load_sources():
    return {
        "source_a": load_source_a(SOURCE_A),
        "source_b": pd.read_csv(SOURCE_B, dtype=str, keep_default_na=False),
        "source_c": pd.read_parquet(SOURCE_C),
    }


def extract_records(raw_sources):
    """Return {user_id: {source: {field: normalized_value}}}."""
    records = {}
    for source in SOURCES:
        frame = raw_sources[source]
        for _, row in frame.iterrows():
            canonical = {}
            for field in FIELD_MAP:
                for column in FIELD_MAP[field][source]:
                    if column in row.index:
                        canonical[field] = CLEANERS[field](row[column])
                        break
            user_id = canonical.get("user_id")
            if user_id is None:
                continue
            records.setdefault(user_id, {})[source] = canonical
    return records


def merge(records):
    merged_rows = []
    conflicts = []

    for user_id in sorted(records):
        per_source = records[user_id]
        row = {"user_id": user_id}

        for field in OUTPUT_FIELDS[1:]:
            present = {src: per_source[src][field]
                       for src in SOURCES
                       if src in per_source and per_source[src].get(field) is not None}

            # Winner: highest-priority source that provides a value.
            selected = None
            for src in SOURCES:
                if src in present:
                    selected = present[src]
                    break

            distinct = set(present.values())
            if len(present) > 1 and len(distinct) > 1:
                conflicts.append({
                    "user_id": user_id,
                    "field": field,
                    "values": {src: present[src] for src in SOURCES if src in present},
                    "selected": selected,
                })

            row[field] = selected

        merged_rows.append(row)

    return merged_rows, conflicts


def write_outputs(merged_rows, conflicts):
    schema = pa.schema([
        ("user_id", pa.int64()),
        ("name", pa.string()),
        ("email", pa.string()),
        ("created_date", pa.string()),
        ("status", pa.string()),
    ])
    table = pa.Table.from_pylist(merged_rows, schema=schema)
    pq.write_table(table, OUT_PARQUET)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2, ensure_ascii=False)
        handle.write("\n")


def main():
    raw_sources = load_sources()
    records = extract_records(raw_sources)
    merged_rows, conflicts = merge(records)
    write_outputs(merged_rows, conflicts)
    print(f"Wrote {len(merged_rows)} users to {OUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUT_CONFLICTS}")


if __name__ == "__main__":
    main()

