import json, re
import pandas as pd
import pyarrow.parquet as pq

t = pq.read_table('merged_users.parquet')
df = t.to_pandas()
schema = dict(t.schema)

# 1. Types
assert schema['user_id'] == 'int64', schema
for c in ['name','email','created_date','status']:
    assert str(schema[c]) == 'string', schema

# 2. Unique users across sources
a = pd.read_json('/data/source_a/users.json')
b = pd.read_csv('/data/source_b/users.csv')
c = pd.read_parquet('/data/source_c/users.parquet')
expected_ids = sorted(set(a['id']) | set(b['user_id']) | set(c['userId']))
assert sorted(df.user_id) == expected_ids, (sorted(df.user_id), expected_ids)
assert df.user_id.is_unique

# 3. Dates
assert df.created_date.map(lambda x: bool(re.fullmatch(r'\d{4}-\d{2}-\d{2}', x))).all()

# 4. Columns exactly as specified
assert list(df.columns) == ['user_id','name','email','created_date','status'], list(df.columns)

# 5. Priority resolution spot checks
row = df.set_index('user_id').loc[101]
assert row['name']=='John Doe' and row['email']=='john@a.com' and row['created_date']=='2024-01-15'
r102 = df.set_index('user_id').loc[102]
assert r102['email']=='jane@a.com' and r102['status']=='inactive'
r103 = df.set_index('user_id').loc[103]
assert r103['name']=='Bob Wilson' and r103['email']=='bob@b.com' and r103['created_date']=='2024-03-01'
r104 = df.set_index('user_id').loc[104]
assert r104['name']=='Alice Brown' and r104['email']=='alice@c.com' and r104['created_date']=='2024-04-01'

# 6. Conflict report structure + consistency
rep = json.load(open('conflicts.json'))
assert rep['total_conflicts'] == len(rep['conflicts']) == 3
assert set(rep.keys()) == {'total_conflicts','conflicts'}
for cf in rep['conflicts']:
    assert set(cf) == {'user_id','field','values','selected'}
    assert cf['user_id'] == 101
    assert cf['field'] in {'name','email','created_date','status'}
    assert cf['selected'] == cf['values']['source_a']
    assert len(set(cf['values'].values())) > 1

# 7. No unseen conflicts: recompute naively from raw sources
def canonical(source, row):
    if source=='a':
        return {'name':row['full_name'],'email':row['email'],'created_date':row['registration_date'],
                'status':row['status'],'user_id':int(row['id'])}
    if source=='b':
        return {'name':row['name'],'email':row['email_address'],'created_date':row['created_at'],
                'status':'active' if row['is_active'] else 'inactive','user_id':int(row['user_id'])}
    return {'name':row['userName'],'email':row['email'],'created_date':row['joined'],
            'status':'active' if row['active'] else 'inactive','user_id':int(row['userId'])}

by_id = {}
for src, frame in [('source_a',a),('source_b',b),('source_c',c)]:
    for _, r in frame.iterrows():
        d = canonical(src[-1], r)
        by_id.setdefault(d['user_id'],{})[src] = d
recomputed = []
for uid, srcs in sorted(by_id.items()):
    for f in ['name','email','created_date','status']:
        vals = {s: srcs[s][f] for s in ['source_a','source_b','source_c'] if s in srcs}
        if len(vals)>1 and len(set(vals.values()))>1:
            recomputed.append((uid,f))
reported = [(c['user_id'],c['field']) for c in rep['conflicts']]
assert recomputed == reported, (recomputed, reported)

print("ALL CHECKS PASSED")
print(f"users={len(df)} conflicts={len(recomputed)}")
